protected void addDocuments()
{
    next addDocuments();
    this.addNDXDocuments();
}

/// <summary>
/// Add Report
/// </summary>
public void addNDXDocuments()
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup

    this.addOther(PrintMgmtDocumentType::Quotation,
        ssrsReportStr(NDXSalesQuotation, ReportOPKLink),
        ssrsReportStr(NDXSalesQuotation, ReportOPKLink),
        #NoCountryRegionId);

}
